steps.command:
printf 'location /admin {
  auth_basic "Restricted";
  auth_basic_user_file /etc/nginx/.htpasswd;
}
location /console {
  auth_basic "Restricted";
  auth_basic_user_file /etc/nginx/.htpasswd;
}
location ~* \.(bak|old|orig|swp|sql|tar|gz|zip)$ {
  deny all;
  return 403;
}
' > /etc/nginx/conf.d/cme-918-url-auth.conf
